<?php $conductores = $db ? $db->query('SELECT c.id_conductor, c.nombre, c.licencia, c.telefono, b.placa FROM conductor c LEFT JOIN buseta b ON b.id_buseta = c.id_buseta ORDER BY c.id_conductor DESC')->fetchAll() : []; $busetas = $db ? $db->query("SELECT id_buseta, placa FROM buseta WHERE estado = 'activa' ORDER BY placa")->fetchAll() : []; ?>
<section class="module-container"><div class="module-heading"><div><span class="eyebrow">GESTIÓN OPERATIVA</span><h1>Conductores</h1><p>Registra y consulta el personal operativo.</p></div><i class="fas fa-id-card module-icon"></i></div><div class="module-grid"><div class="module-card"><h2>Nuevo conductor</h2><form method="post" action="index.php?pg=conductores"><?= csrf_field() ?><input type="hidden" name="action" value="crear_conductor"><label>Nombre completo<input required minlength="3" name="nombre" type="text"></label><label>Licencia<input required name="licencia" type="text" placeholder="C2 o C3"></label><label>Teléfono<input name="telefono" type="tel"></label><label>Bus asignado<select name="id_buseta"><option value="">Sin asignar</option><?php foreach ($busetas as $bus): ?><option value="<?= (int) $bus['id_buseta'] ?>"><?= e($bus['placa']) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary" type="submit">Guardar conductor</button></form></div><div class="module-card table-card"><h2>Conductores registrados</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nombre</th><th>Licencia</th><th>Teléfono</th><th>Bus</th></tr></thead><tbody><?php foreach ($conductores as $conductor): ?><tr><td><?= e($conductor['nombre']) ?></td><td><?= e($conductor['licencia']) ?></td><td><?= e($conductor['telefono']) ?></td><td><?= e($conductor['placa'] ?? 'Sin asignar') ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></section>
